import { FormEvent, useMemo, useState } from 'react'
import { BookOpen, Check, Circle, Inbox, Trash2 } from 'lucide-react'

type ReadingItem = {
  id: number
  title: string
  completed: boolean
  savedAt: string
}

type Filter = 'all' | 'unread' | 'finished'

const starterItems: ReadingItem[] = [
  { id: 1, title: 'The case for doing less', completed: false, savedAt: 'Today' },
  { id: 2, title: 'How to build a calmer internet', completed: false, savedAt: 'Yesterday' },
  { id: 3, title: 'The hidden life of trees', completed: true, savedAt: 'May 18' },
]

function loadItems(): ReadingItem[] {
  try {
    const saved = localStorage.getItem('reading-list-items')
    return saved ? JSON.parse(saved) : starterItems
  } catch {
    return starterItems
  }
}

export default function App() {
  const [items, setItems] = useState<ReadingItem[]>(loadItems)
  const [title, setTitle] = useState('')
  const [filter, setFilter] = useState<Filter>('all')

  const saveItems = (next: ReadingItem[]) => {
    setItems(next)
    localStorage.setItem('reading-list-items', JSON.stringify(next))
  }

  const addItem = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const trimmedTitle = title.trim()
    if (!trimmedTitle) return
    saveItems([
      { id: Date.now(), title: trimmedTitle, completed: false, savedAt: 'Just now' },
      ...items,
    ])
    setTitle('')
  }

  const toggleItem = (id: number) => {
    saveItems(items.map((item) => (item.id === id ? { ...item, completed: !item.completed } : item)))
  }

  const deleteItem = (id: number) => saveItems(items.filter((item) => item.id !== id))

  const visibleItems = useMemo(
    () => items.filter((item) => filter === 'all' || (filter === 'unread' ? !item.completed : item.completed)),
    [items, filter],
  )

  const unreadCount = items.filter((item) => !item.completed).length
  const finishedCount = items.length - unreadCount

  return (
    <div className="min-h-screen bg-canvas">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-5xl items-center justify-between px-5 py-5 sm:px-8">
          <a href="." className="flex items-center gap-3 text-ink" aria-label="Read later home">
            <span className="flex size-9 items-center justify-center rounded-md bg-ink text-surface">
              <BookOpen size={19} strokeWidth={2.2} />
            </span>
            <span className="text-lg font-semibold tracking-tight">Read later</span>
          </a>
          <span className="hidden text-sm text-ink-subtle sm:block">A quiet place for good ideas</span>
        </div>
      </header>

      <main className="mx-auto max-w-5xl px-5 pb-20 pt-12 sm:px-8 sm:pt-16">
        <section className="max-w-2xl">
          <p className="mb-4 text-sm font-semibold uppercase tracking-[0.12em] text-accent">Your reading list</p>
          <h1 className="text-4xl font-semibold tracking-tight text-ink sm:text-5xl">Keep the good stuff close.</h1>
          <p className="mt-5 max-w-xl text-lg leading-8 text-ink-muted">
