          </p>

          <form onSubmit={addItem} className="mt-8 flex flex-col gap-3 sm:flex-row">
            <label htmlFor="article-title" className="sr-only">Article title</label>
            <input
              id="article-title"
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              placeholder="What do you want to read?"
              className="min-h-13 flex-1 rounded-md border border-border-strong bg-surface px-4 text-base text-ink shadow-raised placeholder:text-ink-subtle"
            />
            <button
              type="submit"
              className="min-h-13 rounded-md bg-accent px-6 text-sm font-semibold text-on-accent transition-colors hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-50"
              disabled={!title.trim()}
            >
              Save article
            </button>
          </form>
          <p className="mt-3 text-xs text-ink-subtle">Press Enter to save</p>
        </section>

        <section className="mt-16" aria-labelledby="list-heading">
          <div className="flex flex-col justify-between gap-5 border-b border-border pb-5 sm:flex-row sm:items-end">
            <div>
              <h2 id="list-heading" className="text-2xl font-semibold tracking-tight text-ink">Your list</h2>
              <p className="mt-1 text-sm text-ink-muted">
                {unreadCount === 0 ? 'You are all caught up.' : `${unreadCount} ${unreadCount === 1 ? 'article' : 'articles'} waiting to be read`}
              </p>
            </div>
            <div className="flex gap-1 rounded-md bg-surface-muted p-1" role="group" aria-label="Filter reading list">
