            {visibleItems.length > 0 ? visibleItems.map((item) => (
              <article key={item.id} className="group flex items-center gap-4 py-5">
                <button
                  type="button"
                  onClick={() => toggleItem(item.id)}
                  aria-label={item.completed ? `Mark ${item.title} unread` : `Mark ${item.title} finished`}
                  className={`flex size-6 shrink-0 items-center justify-center rounded-full border transition-colors ${item.completed ? 'border-success bg-success text-on-accent' : 'border-border-strong bg-surface text-transparent hover:border-accent hover:text-accent'}`}
