                  {item.completed ? <Check size={14} strokeWidth={3} /> : <Circle size={12} fill="currentColor" strokeWidth={0} />}
                </button>
                <div className="min-w-0 flex-1">
                  <h3 className={`truncate text-base font-medium ${item.completed ? 'text-ink-subtle line-through' : 'text-ink'}`}>{item.title}</h3>
                  <p className="mt-1 text-xs text-ink-subtle">Saved {item.savedAt}</p>
                </div>
                <button
                  type="button"
                  onClick={() => deleteItem(item.id)}
                  aria-label={`Delete ${item.title}`}
                  className="rounded-sm p-2 text-ink-subtle opacity-100 transition-colors hover:bg-danger-soft hover:text-danger sm:opacity-0 sm:group-hover:opacity-100"
                >
                  <Trash2 size={17} />
                </button>
              </article>
            )) : (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <span className="flex size-12 items-center justify-center rounded-full bg-surface-muted text-ink-subtle"><Inbox size={21} /></span>
                <h3 className="mt-4 text-base font-semibold text-ink">Nothing here yet</h3>
                <p className="mt-1 max-w-xs text-sm text-ink-muted">{filter === 'finished' ? 'Finished articles will appear here.' : 'Add an article above and it will show up here.'}</p>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  )
}

