@import "tailwindcss";

/**
 * The starting design system every generated app inherits.
 *
 * These are *semantic* tokens, not a copy of shadcn's `--background`/`--foreground` set and
 * not a second name for Tailwind's palette. The point is that an app can be restyled from
 * this block alone: change `--color-accent` and every button, link, focus ring and selected
 * row moves with it. Tailwind's own scales are still there and still usable — this adds a
 * layer with intent on top rather than taking anything away.
 *
 * Every foreground/background pair below clears WCAG AA (4.5:1 for text, 3:1 for control
 * borders), which is what keeps a generated app from failing an accessibility audit on
 * colours it never chose. `test/template-design.test.ts` re-computes those ratios, so a
 * palette edit that darkens a surface or lightens a text tone fails a free test rather than
 * a funded run.
 */
@theme {
  /*
   * A warm near-neutral rather than pure grey. It costs nothing, and it is the cheapest way
   * for a generated interface not to look like an unstyled default.
   */
  --color-canvas: #fbfaf9;
  --color-surface: #ffffff;
  --color-surface-muted: #f3f1ed;

  /* Dividers and decorative rules. */
  --color-border: #e3dfd8;
  /*
   * Boundaries a person has to *see* to know a control is there — input, checkbox, outlined
   * button. 3:1 is the threshold for non-text UI, and it has to hold against the *darkest*
   * background the control ever sits on, which is `surface-muted` under a hover, not the
   * canvas. A tone chosen against white alone lands at 2.91:1 there and fails.
   */
  --color-border-strong: #8a8379;

  /* Three text tones, and no more: primary, secondary, and the one for labels and captions. */
  --color-ink: #191817;
  --color-ink-muted: #514c45;
  --color-ink-subtle: #6e675e;

  /*
   * One accent. A second hue is a decision to be argued for, not a default to be filled in —
   * the `-soft` tone is what a tinted background should use, so that "highlighted" does not
   * become "another colour".
   */
  --color-accent: #1c4fd8;
  --color-accent-hover: #1740b4;
  --color-accent-soft: #edf1fe;
  --color-on-accent: #ffffff;

  /*
   * Status, for states rather than for decoration. `danger` gets a hover tone and a
   * foreground of its own rather than a `brightness` filter and a literal white: a filter
   * moves the contrast of a destructive button's label somewhere no check can see it, and
   * that is the one label worth being sure about.
   */
  --color-danger: #b02418;
  --color-danger-hover: #8f1d13;
  --color-danger-soft: #fcefed;
  --color-on-danger: #ffffff;
  --color-success: #0f6b4a;
  --color-success-soft: #eaf4ef;
  --color-warning: #8a5a06;
  --color-warning-soft: #fdf3e3;

  /* Focus is one colour everywhere, so it is recognisable everywhere. */
  --color-ring: #1c4fd8;

  /*
   * A type scale with two regimes. The body range steps gently (12 → 14 → 16 → 18) because
   * those sizes are read rather than scanned, and the display range jumps hard (22 → 28 → 36
   * → 48 → 60) because a heading only creates hierarchy if the difference is obvious at a
   * glance. Line height tightens and tracking goes negative as size grows — large text set at
   * body leading and body tracking is the single most common tell of an unconsidered page.
   */
  --text-xs: 0.75rem;
  --text-xs--line-height: 1.125rem;
  --text-xs--letter-spacing: 0.01em;
  --text-sm: 0.875rem;
  --text-sm--line-height: 1.375rem;
  --text-base: 1rem;
  --text-base--line-height: 1.625rem;
  --text-lg: 1.125rem;
  --text-lg--line-height: 1.75rem;
  --text-xl: 1.375rem;
  --text-xl--line-height: 1.875rem;
  --text-xl--letter-spacing: -0.01em;
  --text-2xl: 1.75rem;
  --text-2xl--line-height: 2.125rem;
  --text-2xl--letter-spacing: -0.015em;
  --text-3xl: 2.25rem;
  --text-3xl--line-height: 2.5rem;
  --text-3xl--letter-spacing: -0.02em;
  --text-4xl: 3rem;
  --text-4xl--line-height: 3.125rem;
  --text-4xl--letter-spacing: -0.025em;
  --text-5xl: 3.75rem;
  --text-5xl--line-height: 3.875rem;
  --text-5xl--letter-spacing: -0.03em;

  /*
   * Every spacing utility is a multiple of this. Kept at 4px, and the rhythm the components
   * below hold to is 4 / 8 / 12 / 16 / 24 / 32 / 48 / 64 — powers and half-steps, never an
   * arbitrary 7 or 13. Consistency between gaps is what reads as deliberate; the exact number
   * rarely matters.
   */
  --spacing: 0.25rem;

  --radius-xs: 0.25rem;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;

  /*
   * Two elevations, because there are two real cases: something sitting on the page, and
   * something floating over it. A third would only ever be used to signal importance that
   * spacing and type should be signalling instead.
   */
  --shadow-raised: 0 1px 2px rgb(25 24 23 / 0.06), 0 1px 3px rgb(25 24 23 / 0.08);
  --shadow-overlay: 0 12px 32px -8px rgb(25 24 23 / 0.18), 0 2px 8px rgb(25 24 23 / 0.08);

  /*
   * A system stack rather than a web font. The preview is photographed by a headless browser
   * seconds after the dev server starts, and a font fetched from a CDN either arrives late or
   * does not arrive — either way the screenshot is of a fallback face. If a project genuinely
   * needs a typeface, self-host it and change this line.
   */
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    background-color: var(--color-canvas);
    color: var(--color-ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  /*
   * One focus treatment for the whole app, defined once. Keyboard users get an unmissable
   * ring on everything; pointer users never see it. Removing an outline without replacing it
   * is the most common accessibility regression in generated code, and this makes the
