import { FormEvent, useMemo, useState } from 'react'
import { BookOpen, Check, Circle, Inbox, Trash2 } from 'lucide-react'

type ReadingItem = {
  id: number
  title: string
  completed: boolean
  savedAt: string
}

type Filter = 'all' | 'unread' | 'finished'

const starterItems: ReadingItem[] = [
  { id: 1, title: 'The case for doing less', completed: false, savedAt: 'Today' },
  { id: 2, title: 'How to build a calmer internet', completed: false, savedAt: 'Yesterday' },
  { id: 3, title: 'The hidden life of trees', completed: true, savedAt: 'May 18' },
]

function loadItems(): ReadingItem[] {
  try {
    const saved = localStorage.getItem('reading-list-items')
    return saved ? JSON.parse(saved) : starterItems
  } catch {
    return starterItems
  }
}

export default function App() {
  const [items, setItems] = useState<ReadingItem[]>(loadItems)
  const [title, setTitle] = useState('')
  const [filter, setFilter] = useState<Filter>('all')

  const saveItems = (next: ReadingItem[]) => {
    setItems(next)
    localStorage.setItem('reading-list-items', JSON.stringify(next))
  }

  const addItem = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const trimmedTitle = title.trim()
    if (!trimmedTitle) return
    saveItems([
      { id: Date.now(), title: trimmedTitle, completed: false, savedAt: 'Just now' },
      ...items,
    ])
    setTitle('')
  }

  const toggleItem = (id: number) => {
    saveItems(items.map((item) => (item.id === id ? { ...item, completed: !item.completed } : item)))
  }

  const deleteItem = (id: number) => saveItems(items.filter((item) => item.id !== id))

  const visibleItems = useMemo(
    () => items.filter((item) => filter === 'all' || (filter === 'unread' ? !item.completed : item.completed)),
    [items, filter],
  )

  const unreadCount = items.filter((item) => !item.completed).length
  const finishedCount = items.length - unreadCount

  return (
    <div className="min-h-screen bg-canvas">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-5xl items-center justify-between px-5 py-5 sm:px-8">
          <a href="." className="flex items-center gap-3 text-ink" aria-label="Read later home">
            <span className="flex size-9 items-center justify-center rounded-md bg-ink text-surface">
              <BookOpen size={19} strokeWidth={2.2} />
            </span>
            <span className="text-lg font-semibold tracking-tight">Read later</span>
          </a>
          <span className="hidden text-sm text-ink-subtle sm:block">A quiet place for good ideas</span>
        </div>
      </header>

      <main className="mx-auto max-w-5xl px-5 pb-20 pt-12 sm:px-8 sm:pt-16">
        <section className="max-w-2xl">
          <p className="mb-4 text-sm font-semibold uppercase tracking-[0.12em] text-accent">Your reading list</p>
          <h1 className="text-4xl font-semibold tracking-tight text-ink sm:text-5xl">Keep the good stuff close.</h1>
          <p className="mt-5 max-w-xl text-lg leading-8 text-ink-muted">
            Save something for later by typing its title below. Come back when you have a little more time.
          </p>

          <form onSubmit={addItem} className="mt-8 flex flex-col gap-3 sm:flex-row">
            <label htmlFor="article-title" className="sr-only">Article title</label>
            <input
              id="article-title"
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              placeholder="What do you want to read?"
              className="min-h-13 flex-1 rounded-md border border-border-strong bg-surface px-4 text-base text-ink shadow-raised placeholder:text-ink-subtle"
            />
            <button
              type="submit"
              className="min-h-13 rounded-md bg-accent px-6 text-sm font-semibold text-on-accent transition-colors hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-50"
              disabled={!title.trim()}
            >
              Save article
            </button>
          </form>
          <p className="mt-3 text-xs text-ink-subtle">Press Enter to save</p>
        </section>

        <section className="mt-16" aria-labelledby="list-heading">
          <div className="flex flex-col justify-between gap-5 border-b border-border pb-5 sm:flex-row sm:items-end">
            <div>
              <h2 id="list-heading" className="text-2xl font-semibold tracking-tight text-ink">Your list</h2>
              <p className="mt-1 text-sm text-ink-muted">
                {unreadCount === 0 ? 'You are all caught up.' : `${unreadCount} ${unreadCount === 1 ? 'article' : 'articles'} waiting to be read`}
              </p>
            </div>
            <div className="flex gap-1 rounded-md bg-surface-muted p-1" role="group" aria-label="Filter reading list">
              {([['all', 'All'], ['unread', 'Unread'], ['finished', 'Finished']] as [Filter, string][]).map(([value, label]) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setFilter(value)}
                  className={`rounded-sm px-3 py-1.5 text-sm font-medium transition-colors ${filter === value ? 'bg-surface text-ink shadow-raised' : 'text-ink-muted hover:text-ink'}`}
                  aria-pressed={filter === value}
                >
                  {label}
                  <span className="ml-1.5 text-xs text-ink-subtle">{value === 'all' ? items.length : value === 'unread' ? unreadCount : finishedCount}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mt-2 divide-y divide-border">
            {visibleItems.length > 0 ? visibleItems.map((item) => (
              <article key={item.id} className="group flex items-center gap-4 py-5">
                <button
                  type="button"
                  onClick={() => toggleItem(item.id)}
                  aria-label={item.completed ? `Mark ${item.title} unread` : `Mark ${item.title} finished`}
                  className={`flex size-6 shrink-0 items-center justify-center rounded-full border transition-colors ${item.completed ? 'border-success bg-success text-on-accent' : 'border-border-strong bg-surface text-transparent hover:border-accent hover:text-accent'}`}
                >
                  {item.completed ? <Check size={14} strokeWidth={3} /> : <Circle size={12} fill="currentColor" strokeWidth={0} />}
                </button>
                <div className="min-w-0 flex-1">
                  <h3 className={`truncate text-base font-medium ${item.completed ? 'text-ink-subtle line-through' : 'text-ink'}`}>{item.title}</h3>
                  <p className="mt-1 text-xs text-ink-subtle">Saved {item.savedAt}</p>
                </div>
                <button
                  type="button"
                  onClick={() => deleteItem(item.id)}
                  aria-label={`Delete ${item.title}`}
                  className="rounded-sm p-2 text-ink-subtle opacity-100 transition-colors hover:bg-danger-soft hover:text-danger sm:opacity-0 sm:group-hover:opacity-100"
                >
                  <Trash2 size={17} />
                </button>
              </article>
            )) : (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <span className="flex size-12 items-center justify-center rounded-full bg-surface-muted text-ink-subtle"><Inbox size={21} /></span>
                <h3 className="mt-4 text-base font-semibold text-ink">Nothing here yet</h3>
                <p className="mt-1 max-w-xs text-sm text-ink-muted">{filter === 'finished' ? 'Finished articles will appear here.' : 'Add an article above and it will show up here.'}</p>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  )
}

